mapper.select:
/** * selectWorkChgMngList : isry.couns.mngr.atrzmng.mapper.WorkChgMngMapper : 근무변경 목록조회 */ SELECT AA.INDEX_SN AS INDEX_SN /** 일련번호(PK) **/ , COUNT(*) OVER() AS TOTAL_COUNT , AA.CHG_DMND_ID AS CNSLTNT_ID /** 신청자ID **/ , C##RG.DEC_B64(CC.FLNM_ENCPT) AS CNSLTNT_NM /** 신청자명 **/ , SUBSTR(AA.CHG_DMND_WORK_YMD, 1,4)||'-'||SUBSTR(AA.CHG_DMND_WORK_YMD, 5,2)||'-'||SUBSTR(AA.CHG_DMND_WORK_YMD, 7,2) AS CHG_DMND_WORK_YMD , AA.CHG_DMND_WORK_HR_CN AS CHG_DMND_WORK_HR_CN , AA.CHG_TRGT_ID AS CHG_TRGT_ID , SUBSTR(AA.CHG_TRGT_WORK_YMD, 1,4)||'-'||SUBSTR(AA.CHG_TRGT_WORK_YMD, 5,2)||'-'||SUBSTR(AA.CHG_TRGT_WORK_YMD, 7,2) AS CHG_TRGT_WORK_YMD , AA.CHG_TRGT_WORK_HR_CN AS CHG_TRGT_WORK_HR_CN , ( SELECT C##RG.DEC_B64(A1.FLNM_ENCPT) FROM SCA100 A1 , SAA200 B1 WHERE 1=1 AND A1.ENFSN_NO = B1.ENFSN_NO AND B1.USER_ID = AA.CHG_TRGT_ID ) AS CHG_TRGT_NM , TO_CHAR(AA.FRST_REG_DT, 'YYYYMMDD') AS REG_YMD /** 등록일 **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APRV_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APRV_STTS_SE_CD ) AS PRCS_STTS_SE_CD /** 상태 **/ , AA.SMS_SNDNG_YN AS SMS_SNDNG_YN /** 발송상태 **/ , DECODE(AA.APRV_STTS_SE_CD,'0','Y','N') AS P_YN /** 상태가 대기(1)일 경우 check **/ , CASE WHEN ((AA.APRV_STTS_SE_CD = '2' OR AA.APRV_STTS_SE_CD = '3') AND AA.SMS_SNDNG_YN = 'N') THEN 'Y' ELSE 'N' END AS MSG_YN /** 처리상태가 승인(2) or 반려(3) 이고 문자발송이 N인 경우 check **/ FROM AYC140 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.CHG_DMND_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO(+) /* 종사자번호 */ AND CC.DEL_YN = 'N' /* 종사자 삭제여부 */
AND CC.OGDP_DEPT_CD = #{deptCd}
AND AA.CHG_DMND_ID LIKE '%' || #{userId} || '%'
AND CC.FLNM_ENCPT = C##RG.ENC_B64(#{userNm})
AND AA.APRV_STTS_SE_CD = #{prcsSttsSeCd}
AND AA.FRST_REG_DT >= TO_DATE(#{bgngYmd} || '000000', 'YYYYMMDDHH24MISS')
AND AA.FRST_REG_DT < TO_DATE(#{endYmd} || '000000', 'YYYYMMDDHH24MISS')+1
ORDER BY AA.FRST_REG_DT DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY /** 페이징 처리 **/

/** * selectWorkChgMngDetail : isry.couns.mngr.atrzmng.mapper.WorkChgMngMapper : 근무변경 상세조회 */ WITH MAIN_DATA AS ( SELECT AA.* , CC.FLNM_ENCPT AS CHG_REQUES_NM FROM AYC140 AA /** 근무변경허가원 **/ , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.CHG_DMND_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO
AND AA.INDEX_SN = #{indexSn}
AND AA.CHG_DMND_ID = #{userId}
) SELECT MD.INDEX_SN AS INDEX_SN , MD.CHG_DMND_ID AS CHG_DMND_ID /** 변경요청아이디 **/ , C##RG.DEC_B64(MD.CHG_REQUES_NM) AS CHG_REQUES_NM /** 변경요청자명 **/ , MD.CHG_CS_CN AS CHG_CS_CN /** 변경사유내용 **/ , MD.FRST_REG_DT AS REG_YMD /** 등록일자 **/ , MD.RJCT_CS_CN AS RJCT_CS_CN /** 반려사유내용 **/ , MD.APRV_PSBLTY_YN AS APRV_PSBLTY_YN /** 승인가능여부 **/ , MD.APRV_STTS_SE_CD AS APRV_STTS_SE_CD /** 처리상태구분코드 **/ , MD.CHG_TRGT_SN AS CHG_TRGT_SN /**변경대상 일련번호**/ , MD.CHG_DMND_SN AS CHG_DMND_SN /**변경요청 일련번호**/ , MD.CHG_TRGT_WORK_YMD AS CHG_TRGT_WORK_YMD , MD.CHG_TRGT_WORK_HR_CN AS CHG_TRGT_WORK_HR_CN , MD.CHG_DMND_WORK_YMD AS CHG_DMND_WORK_YMD , MD.CHG_DMND_WORK_HR_CN AS CHG_DMND_WORK_HR_CN , MD.CHG_TRGT_ID , ( SELECT C##RG.DEC_B64(B1.FLNM_ENCPT) AS CHG_TRGT_NM FROM SAA200 A1 , SCA100 B1 WHERE 1=1 AND A1.USER_ID = MD.CHG_TRGT_ID AND A1.ENFSN_NO = B1.ENFSN_NO ) AS CHG_TRGT_NM , WORK_DEMAND.YMD_HR AS WORK_YMD_DEMAND , WORK_TARGET.YMD_HR AS WORK_YMD_TARGET , WORK_DEMAND.TASKWK_SCHDL_SN_DEMAND AS TASKWK_SCHDL_SN_DEMAND /**근무배정표 일별(AYC100) 근무변경 요청자의 업무일정 일련번호**/ , WORK_TARGET.TASKWK_SCHDL_SN_TARGET AS TASKWK_SCHDL_SN_TARGET /**근무배정표 일별(AYC100) 근무변경 대상자의 업무일정 일련번호**/ , WORK_DEMAND.TASKWK_TYPE_DEPT_CD_DEMAND AS TASKWK_TYPE_DEPT_CD_DEMAND , WORK_TARGET.TASKWK_TYPE_DEPT_CD_TARGET AS TASKWK_TYPE_DEPT_CD_TARGET , WORK_TARGET.USER_ID_TARGET AS USER_ID_TARGET , WORK_DEMAND.USER_ID_DEMAND AS USER_ID_DEMAND , C##RG.DEC_B64(WORK_TARGET.USER_NM_TARGET) AS USER_NM_TARGET , C##RG.DEC_B64(WORK_DEMAND.USER_NM_DEMAND) AS USER_NM_DEMAND FROM MAIN_DATA MD , ( SELECT AA1.WORK_YMD || '('|| BB1.BGNG_HR || '~' || BB1.END_HR || ')' AS YMD_HR , AA1.TASKWK_SCHDL_SN AS TASKWK_SCHDL_SN_DEMAND /** 업무일정일련번호 **/ , AA1.USER_ID AS USER_ID_DEMAND , AA1.TASKWK_TYPE_DEPT_CD AS TASKWK_TYPE_DEPT_CD_DEMAND , DD1.FLNM_ENCPT AS USER_NM_DEMAND FROM AYC100 AA1 /**근무배정표일별**/ , MAIN_DATA MD , AYC110 BB1 /**근무배정표월별**/ , SAA200 CC1 , SCA100 DD1 WHERE 1=1 AND MD.CHG_DMND_SN = AA1.TASKWK_SCHDL_SN AND AA1.BIZ_PLAN_MNG_NO = BB1.BIZ_PLAN_MNG_NO AND AA1.USER_ID = CC1.USER_ID AND CC1.ENFSN_NO = DD1.ENFSN_NO ) AS WORK_DEMAND , ( SELECT AA2.WORK_YMD || '('|| BB2.BGNG_HR || '~' || BB2.END_HR || ')' AS YMD_HR , AA2.TASKWK_SCHDL_SN AS TASKWK_SCHDL_SN_TARGET /** 업무일정일련번호 **/ , AA2.USER_ID AS USER_ID_TARGET , AA2.TASKWK_TYPE_DEPT_CD AS TASKWK_TYPE_DEPT_CD_TARGET , DD2.FLNM_ENCPT AS USER_NM_TARGET FROM AYC100 AA2 /**근무배정표일별**/ , MAIN_DATA MD , AYC110 BB2 /**근무배정표월별**/ , SAA200 CC2 , SCA100 DD2 WHERE 1=1 AND MD.CHG_TRGT_SN = AA2.TASKWK_SCHDL_SN AND AA2.BIZ_PLAN_MNG_NO = BB2.BIZ_PLAN_MNG_NO AND AA2.USER_ID = CC2.USER_ID AND CC2.ENFSN_NO = DD2.ENFSN_NO ) AS WORK_TARGET WHERE 1=1 AND MD.CHG_DMND_SN = WORK_DEMAND.TASKWK_SCHDL_SN_DEMAND(+) AND MD.CHG_TRGT_SN = WORK_TARGET.TASKWK_SCHDL_SN_TARGET(+)

mapper.update:
/**
*		processWorkChgMng1 : isry.couns.mngr.atrzmng.mapper.WorkChgMngMapper : 근무변경 상태변경 AYC140
*/
	UPDATE 
			AYC140		AA		/** 근무변경허가원 **/
	SET
			AA.APRV_STTS_SE_CD	=	#{prcsSttsSeCd}
		,	AA.LAST_MDFR_ID		=	#{loginId}
		,	AA.LAST_MDFCN_DT	=	SYSDATE


		,	AA.RJCT_CS_CN		=	#{rjctCsCn}



		,   AA.RJCT_CS_CN       =   null

	WHERE	1=1
		AND	AA.INDEX_SN			=	#{indexSn}

/**
*		processWorkChgMng2 : isry.couns.mngr.atrzmng.mapper.WorkChgMngMapper : 근무변경 상태변경 AYC100
*/
	UPDATE
			AYC100		AA		/** 근무배정표 일별 **/
	SET
			AA.USER_ID			=	#{demandId}
		,	AA.LAST_MDFR_ID		=	#{loginId}
		,	AA.LAST_MDFCN_DT	=	SYSDATE
	WHERE	1=1
		AND	AA.TASKWK_SCHDL_SN	=	#{targetSn}

/**
*		processWorkChgMng3 : isry.couns.mngr.atrzmng.mapper.WorkChgMngMapper : 근무변경 상태변경 AYC100
*/
	UPDATE
			AYC100		AA		/** 근무배정표 일별 **/
	SET
			AA.USER_ID			=	#{targetId}
		,	AA.LAST_MDFR_ID		=	#{loginId}
		,	AA.LAST_MDFCN_DT	=	SYSDATE
	WHERE	1=1
		AND	AA.TASKWK_SCHDL_SN	=	#{demandSn}

/**
*		processWorkChgMng4 : isry.couns.mngr.atrzmng.mapper.WorkChgMngMapper : 근무변경 상태변경 AYC120
*/
	UPDATE
			AYC120		AA		/** 근무배정표 아웃리치 **/
	SET
			AA.USER_ID			=	#{demandId}
		,	AA.LAST_MDFR_ID		=	#{loginId}
		,	AA.LAST_MDFCN_DT	=	SYSDATE
	WHERE	1=1
		AND	AA.TASKWK_SCHDL_SN	=	#{targetSn}

/**
*		processWorkChgMng5 : isry.couns.mngr.atrzmng.mapper.WorkChgMngMapper : 근무변경 상태변경 AYC120
*/
	UPDATE
			AYC120		AA		/** 근무배정표 아웃리치 **/
	SET
			AA.USER_ID			=	#{targetId}
		,	AA.LAST_MDFR_ID		=	#{loginId}
		,	AA.LAST_MDFCN_DT	=	SYSDATE
	WHERE	1=1
		AND	AA.TASKWK_SCHDL_SN	=	#{demandSn}

