/**
*		processWorkChgMngBatch : isry.couns.mngr.atrzmng.mapper.WorkChgMngMapper : 근무변경 일괄승인
*/
	{call AY_SP_UPDATE_WORK_CHG_BATCH(			
			#{loginId, mode=IN, jdbcType=VARCHAR}
		,	#{retVal, mode=OUT, jdbcType=VARCHAR}
	)}

