UPDATE
        AYC100      TARGET1
SET
        TARGET1.USER_ID         =   #{TARGET_DMND_ID}
    ,   TARGET1.LAST_MDFR_ID    =   #{VAR_P_IN_LOGINID}
    ,   TARGET1.LAST_MDFCN_DT   =   SYSDATE
WHERE   1=1
    AND TARGET1.TASKWK_SCHDL_SN =   #{TARGET_TRGT_SN}

UPDATE
        AYC100      TARGET2
SET
        TARGET2.USER_ID         =   #{TARGET_TRGT_ID}
    ,   TARGET2.LAST_MDFR_ID    =   #{VAR_P_IN_LOGINID}
    ,   TARGET2.LAST_MDFCN_DT   =   SYSDATE
WHERE   1=1
    AND TARGET2.TASKWK_SCHDL_SN =   #{TARGET_DMND_SN}

UPDATE
        AYC140      AA_SRC
SET
        AA_SRC.APRV_STTS_SE_CD  =   #{VAR_PRC_SE_CD}
    ,   AA_SRC.LAST_MDFR_ID     =   #{VAR_P_IN_LOGINID}
    ,   AA_SRC.LAST_MDFCN_DT    =   SYSDATE
WHERE   1=1
    AND AA_SRC.INDEX_SN         =   #{INDEX_SN}

UPDATE 
        AYC120      TARGET_OUTREACH1
SET
        TARGET_OUTREACH1.USER_ID            =   #{TARGET_DMND_ID}
    ,   TARGET_OUTREACH1.LAST_MDFR_ID       =   #{VAR_P_IN_LOGINID}
    ,   TARGET_OUTREACH1.LAST_MDFCN_DT      =   SYSDATE
WHERE   1=1
    AND TARGET_OUTREACH1.TASKWK_SCHDL_SN    =   #{TARGET_TRGT_SN}

UPDATE 
        AYC120      TARGET_OUTREACH2
SET
        TARGET_OUTREACH2.USER_ID            =   #{TARGET_TRGT_ID}
    ,   TARGET_OUTREACH2.LAST_MDFR_ID       =   #{VAR_P_IN_LOGINID}
    ,   TARGET_OUTREACH2.LAST_MDFCN_DT      =   SYSDATE
WHERE   1=1
    AND TARGET_OUTREACH2.TASKWK_SCHDL_SN    =   #{TARGET_DMND_SN}
